class N {
  final int id;
  late N next;
  N(this.id);
}

int josephus(int n, int k) {
  final first = N(1);
  var prev = first;
  for (var i = 2; i <= n; i++) {
    final node = N(i);
    prev.next = node;
    prev = node;
  }
  prev.next = first;
  var cur = prev;
  while (!identical(cur.next, cur)) {
    for (var i = 1; i < k; i++) {
      cur = cur.next;
    }
    cur.next = cur.next.next;
  }
  return cur.id;
}

void main() {
  print(josephus(4, 2));
}
```

